package com.pethop.report;
import com.pethop.admin.AdminAuditService; import com.pethop.common.exception.ApiException; import com.pethop.common.response.PageResponse; import com.pethop.notification.NotificationService; import com.pethop.pet.*; import com.pethop.report.dto.*; import com.pethop.security.SecurityUser; import java.time.Instant; import java.util.List; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ReportService{
 private final UserReportRepository reports;private final PetRepository pets;private final NotificationService notifications;private final AdminAuditService audit; private static final List<ReportStatus> OPEN=List.of(ReportStatus.SUBMITTED,ReportStatus.UNDER_REVIEW);
 public ReportService(UserReportRepository r,PetRepository p,NotificationService n,AdminAuditService a){reports=r;pets=p;notifications=n;audit=a;}
 @Transactional public ReportResponse create(UUID petId,SecurityUser reporter,CreateReportRequest request){Pet pet=pets.findByIdAndDeletedAtIsNull(petId).orElseThrow(()->ApiException.notFound("Mascota no encontrada."));if(reports.existsByReporterIdAndPetIdAndStatusIn(reporter.id(),petId,OPEN))throw ApiException.conflict("Ya existe un reporte abierto para esta publicación.");UserReport r=new UserReport();r.setReporter(reporter.user());r.setPet(pet);r.setCategory(request.category());r.setDescription(request.description().trim());return ReportResponse.from(reports.save(r));}
 @Transactional(readOnly=true) public PageResponse<ReportResponse> list(int page,int size){return PageResponse.from(reports.findAllByOrderByCreatedAtDesc(PageRequest.of(page,size)),ReportResponse::from);}
 @Transactional(readOnly=true) public ReportResponse get(UUID id){return ReportResponse.from(find(id));}
 @Transactional public ReportResponse act(UUID id,SecurityUser admin,ReportActionRequest request){UserReport r=reports.findByIdForUpdate(id).orElseThrow(()->ApiException.notFound("Reporte no encontrado."));ReportStatus old=r.getStatus();ReportStatus next=switch(request.action()){case START_REVIEW->ReportStatus.UNDER_REVIEW;case RESOLVE->ReportStatus.RESOLVED;case DISMISS->ReportStatus.DISMISSED;};if(old==ReportStatus.RESOLVED||old==ReportStatus.DISMISSED)throw ApiException.conflict("El reporte ya fue cerrado.");if(request.action()!=ReportAction.START_REVIEW&&(request.details()==null||request.details().isBlank()))throw ApiException.badRequest("Debe indicar los detalles de la resolución.");if(request.action()==ReportAction.START_REVIEW&&old!=ReportStatus.SUBMITTED)throw ApiException.conflict("El reporte ya está en revisión.");r.setStatus(next);if(next==ReportStatus.RESOLVED||next==ReportStatus.DISMISSED){r.setResolutionDetails(request.details().trim());r.setResolvedBy(admin.user());r.setResolvedAt(Instant.now());notifications.create(r.getReporter(),"REPORT_UPDATE","Actualización de reporte",request.details().trim(),"REPORT",r.getId());}reports.save(r);audit.record(admin.user(),"REPORT_"+request.action(),"REPORT",id,old.name(),next.name(),request.details());return ReportResponse.from(r);}
 private UserReport find(UUID id){return reports.findById(id).orElseThrow(()->ApiException.notFound("Reporte no encontrado."));}
}
